<?php
namespace Dth\Crm\Services;
use Dth\Crm\Models\{Lead,ContactQualification}; use Dth\Crm\Support\CodeGenerator; use Illuminate\Support\Facades\DB;
final class LeadService {public function __construct(private CodeGenerator $codes){}
 public function create(array $data):Lead{return DB::transaction(function()use($data){if(!empty($data['submission_reference'])){$existing=Lead::where('submission_reference',$data['submission_reference'])->first();if($existing)return $existing;} $duplicate=$this->findDuplicate($data);$status=$duplicate?'duplicate':'new';$lead=Lead::create(['lead_code'=>$this->codes->make('LD'),'submission_reference'=>$data['submission_reference']??null,'contact_id'=>$data['contact_id']??null,'company_id'=>$data['company_id']??null,'source'=>$data['source']??'manual','source_detail'=>$data['source_detail']??null,'title'=>$data['title']??null,'service_interest'=>$data['service_interest']??null,'service_reference'=>$data['service_reference']??null,'estimated_value'=>$data['estimated_value']??null,'intake_status'=>$status,'attribution'=>$data['attribution']??[],'form_answers'=>$data['form_answers']??[],'metadata'=>array_merge($data['metadata']??[], $duplicate?['duplicate_of'=>$duplicate->id]:[])]);ContactQualification::create(['lead_id'=>$lead->id,'contact_id'=>$lead->contact_id,'status'=>$duplicate?'duplicate':'new','service_interest'=>$lead->service_interest,'estimated_value'=>$lead->estimated_value]);return $lead->fresh(['qualification']);});}
 public function findDuplicate(array $data):?Lead{$days=(int)config('dth-crm.deduplication.lead_window_days',30);$q=Lead::where('created_at','>=',now()->subDays($days))->whereNotIn('intake_status',['closed','spam']);if(!empty($data['contact_id']))$q->where('contact_id',$data['contact_id']);elseif(!empty($data['company_id']))$q->where('company_id',$data['company_id']);else return null;if(!empty($data['service_reference']))$q->where('service_reference',$data['service_reference']);return $q->first();}
}
